package lockfile

import (
	"slices"
	"testing"
)

// Written by `gh actions-lock` v0.1.6 onboarding one workflow in an isolated tree, verbatim. The
// fix run narrowed `actions/checkout@v4` and `actions/upload-pages-artifact@v3` in the workflow
// and in the lock; the transitive `actions/upload-artifact@v4` keeps the ref the composite wrote,
// because the tool cannot rewrite somebody else's action.
const nestedLock = `# This file is machine-generated by ` + "`gh actions-lock`" + `.
# Do not edit by hand; run ` + "`gh actions-lock`" + ` to update.
# Docs: https://gh.io/actions-lockfile
version: 'v0.0.2'
workflows:
    '.github/workflows/pages.yml':
        - 'actions/checkout@v4.4.0'
        - 'actions/upload-pages-artifact@v3.0.1'
dependencies:
    'actions/checkout@v4.4.0':
        ref: 'v4.4.0'
        commit: 'sha1-11d5960a326750d5838078e36cf38b85af677262'
        owner_id: 44036562
        repo_id: 197814629
    'actions/upload-artifact@v4':
        ref: 'v4'
        commit: 'sha1-ea165f8d65b6e75b540449e92b4886f43607fa02'
        owner_id: 44036562
        repo_id: 192625955
    'actions/upload-pages-artifact@v3.0.1':
        ref: 'v3.0.1'
        commit: 'sha1-56afc609e74202658d3ffba0e8f6dda462b719fa'
        owner_id: 44036562
        repo_id: 496012378
        uses:
            - 'actions/upload-artifact@v4'
`

func dependencyByPin(t *testing.T, deps []Dependency, pin string) Dependency {
	t.Helper()
	for _, d := range deps {
		if d.Pin == pin {
			return d
		}
	}
	t.Fatalf("no dependency %s among %d", pin, len(deps))
	return Dependency{}
}

// Every entry is read with the commit it selects and the identity the lock attributes to it. The
// numeric ids are what detect a transferred repository, so they are kept even though nothing here
// verifies them.
func TestEveryLockedDependencyIsReadWithItsSelectionAndIdentity(t *testing.T) {
	lock, err := Read(writeLock(t, nestedLock))
	if err != nil {
		t.Fatalf("reading the lock: %v", err)
	}
	deps := lock.Dependencies()
	if len(deps) != 3 {
		t.Fatalf("read %d dependencies, want 3", len(deps))
	}
	pages := dependencyByPin(t, deps, "actions/upload-pages-artifact@v3.0.1")
	want := Dependency{
		Pin: "actions/upload-pages-artifact@v3.0.1", Owner: "actions", Repo: "upload-pages-artifact",
		Ref: "v3.0.1", ResolvedFrom: "v3.0.1",
		Algorithm: "sha1", Digest: "56afc609e74202658d3ffba0e8f6dda462b719fa",
		OwnerID: 44036562, RepoID: 496012378,
		Uses: []string{"actions/upload-artifact@v4"},
	}
	if pages.Pin != want.Pin || pages.Owner != want.Owner || pages.Repo != want.Repo ||
		pages.Ref != want.Ref || pages.ResolvedFrom != want.ResolvedFrom ||
		pages.Algorithm != want.Algorithm || pages.Digest != want.Digest ||
		pages.OwnerID != want.OwnerID || pages.RepoID != want.RepoID ||
		!slices.Equal(pages.Uses, want.Uses) {
		t.Errorf("read %+v, want %+v", pages, want)
	}
}

// The pin key's ref and the entry's ref field answer different questions: what was asked for,
// and what the tool resolved it from. An entry keyed by commit and narrowed to a tag disagrees
// with itself by design, and collapsing the two would lose the request.
func TestADependencyKeepsTheRequestedRefApartFromTheOneItWasResolvedFrom(t *testing.T) {
	lock, err := Read(writeLock(t, coveredLock))
	if err != nil {
		t.Fatalf("reading the lock: %v", err)
	}
	cache := dependencyByPin(t, lock.Dependencies(),
		"actions/cache@55cc8345863c7cc4c66a329aec7e433d2d1c52a9")
	if cache.Ref != "55cc8345863c7cc4c66a329aec7e433d2d1c52a9" {
		t.Errorf("ref = %q, want the commit the key names", cache.Ref)
	}
	if cache.ResolvedFrom != "v6.1.0" {
		t.Errorf("resolved from = %q, want the entry's own ref field", cache.ResolvedFrom)
	}
}

// Refutes the parser's own description. `File.Workflows` is documented as each workflow's flat
// transitive closure, and the pinned CLI does not write it that way: a workflow lists the pins it
// names, and what a composite pulls in is reachable only through that entry's `uses:`.
func TestAWorkflowEntryListsOnlyThePinsTheWorkflowNames(t *testing.T) {
	lock, err := Read(writeLock(t, nestedLock))
	if err != nil {
		t.Fatalf("reading the lock: %v", err)
	}
	var pins []string
	for _, w := range lock.WorkflowPins() {
		if w.Path == ".github/workflows/pages.yml" {
			pins = append(pins, w.Pin)
		}
	}
	want := []string{"actions/checkout@v4.4.0", "actions/upload-pages-artifact@v3.0.1"}
	if !slices.Equal(pins, want) {
		t.Errorf("pages.yml lists %v, want %v", pins, want)
	}
	if slices.Contains(pins, "actions/upload-artifact@v4") {
		t.Error("the transitive pin is listed under the workflow; the DAG is no longer the only path")
	}
}

// A lock nothing can read has no graph to report. Returning its entries anyway would let a
// schema this consumer does not understand select commits.
func TestALockThatCannotBeReadHasNoGraph(t *testing.T) {
	for name, root := range map[string]string{
		"unsupported": writeLock(t, futureLock),
		"absent":      t.TempDir(),
	} {
		lock, err := Read(root)
		if err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		if deps := lock.Dependencies(); len(deps) != 0 {
			t.Errorf("%s: read %d dependencies, want none", name, len(deps))
		}
		if pins := lock.WorkflowPins(); len(pins) != 0 {
			t.Errorf("%s: read %d workflow pins, want none", name, len(pins))
		}
	}
}

// The parser validates only the entries the workflows it is handed list, and a lockfile is not a
// workflow: handing it the lock's own path validated nothing. An entry whose commit is not a
// commit would then select `main` as though it were one.
func TestAnEntryWhoseCommitIsNotACommitMakesTheLockUnsupported(t *testing.T) {
	for name, entry := range map[string]string{
		"listed by a workflow": "actions/checkout@v4",
		"reached only nested":  "actions/cache@v4",
	} {
		lock, err := Read(writeLock(t, lockHeaderForTests+`workflows:
    '.github/workflows/ci.yml':
        - 'actions/checkout@v4'
dependencies:
    'actions/checkout@v4':
        ref: 'v4'
        commit: '`+commitFor(entry, "actions/checkout@v4")+`'
        owner_id: 44036562
        repo_id: 197814629
        uses:
            - 'actions/cache@v4'
    'actions/cache@v4':
        ref: 'v4'
        commit: '`+commitFor(entry, "actions/cache@v4")+`'
        owner_id: 44036562
        repo_id: 215566462
`))
		if err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		if lock.Coverage != Unsupported {
			t.Errorf("%s: coverage = %q, want %q", name, lock.Coverage, Unsupported)
		}
		if deps := lock.Dependencies(); len(deps) != 0 {
			t.Errorf("%s: an unreadable lock reported %d dependencies", name, len(deps))
		}
	}
}

const lockHeaderForTests = "version: 'v0.0.2'\n"

// commitFor gives the named entry a commit that is not one, and every other a real commit.
func commitFor(broken, pin string) string {
	if pin == broken {
		return "sha1-main"
	}
	return "sha1-11d5960a326750d5838078e36cf38b85af677262"
}

// Only a digest of the right length and alphabet names a commit, whatever the parser let
// through: a selection becomes a ref the queue checks out.
func TestOnlyADigestOfTheRightShapeNamesACommit(t *testing.T) {
	const sha1 = "11D5960A326750D5838078E36CF38B85AF677262"
	sha256 := "5f70bf18a086007016e948b04aed3b82103a36bea41755b6cddfaf10ace3c6ef"
	for commit, want := range map[string]string{
		"sha1-" + sha1:       "11d5960a326750d5838078e36cf38b85af677262",
		"sha256-" + sha256:   sha256,
		"sha1-main":          "",
		"sha1-11d5960":       "",
		"sha1-" + sha256:     "",
		"sha256-" + sha1:     "",
		"md5-" + sha1:        "",
		sha1:                 "",
		"sha1-" + sha1 + "z": "",
	} {
		if _, got := splitCommit(commit); got != want {
			t.Errorf("splitCommit(%q) = %q, want %q", commit, got, want)
		}
	}
}
